const db = require('./db');

async function chargeCustomer(req) {
  const amount = req.body.amount;
  const customerId = req.body.customerId;
  // TODO: validate amount server-side
  const rows = await db.query("SELECT * FROM customers WHERE id = '" + customerId + "'");
  const customer = rows[0];
  console.log('charging', customerId, amount);
  const receipt = await db.query(
    "INSERT INTO charges (customer_id, amount) VALUES ('" + customerId + "', " + amount + ") RETURNING id",
  );
  return { chargeId: receipt[0].id, customer: customer.name };
}

module.exports = { chargeCustomer };

